CREATE TABLE daily_usage_reservations (attempt_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), model_id TEXT NOT NULL, pool TEXT NOT NULL, unit TEXT NOT NULL CHECK(unit IN ('tokens','nanodollars')), day TEXT NOT NULL, reserved_units INTEGER NOT NULL CHECK(reserved_units > 0 AND reserved_units <= 9007199254740991), limit_units INTEGER NOT NULL CHECK(limit_units > 0 AND limit_units <= 9007199254740991), owner_nonce TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX daily_usage_pool_day ON daily_usage_reservations(pool,day);
CREATE TABLE daily_usage_cancellations (attempt_id TEXT PRIMARY KEY REFERENCES daily_usage_reservations(attempt_id), owner_nonce TEXT NOT NULL, created_at TEXT NOT NULL, reason TEXT NOT NULL);
CREATE INDEX vendor_calls_model_day ON vendor_calls(model_requested,created_at);
CREATE INDEX runs_actor_day ON runs(actor,created_at);
CREATE VIEW daily_vendor_usage AS WITH normalized AS (SELECT v.*, CASE WHEN json_valid(usage_json) THEN usage_json ELSE '{}' END AS safe_usage, CASE WHEN cost_nano IS NOT NULL AND length(cost_nano) BETWEEN 1 AND 16 AND cost_nano NOT GLOB '*[^0-9]*' AND (cost_nano='0' OR substr(cost_nano,1,1)!='0') AND CAST(cost_nano AS INTEGER) <= 9007199254740991 THEN CAST(cost_nano AS INTEGER) END AS nano_units FROM vendor_calls v) SELECT attempt_id,run_id,fingerprint,role,model_requested,created_at,nano_units, CASE WHEN nano_units IS NOT NULL AND json_type(safe_usage,'$.input_tokens')='integer' AND json_type(safe_usage,'$.output_tokens')='integer' AND json_extract(safe_usage,'$.input_tokens') BETWEEN 0 AND 9007199254740991 AND json_extract(safe_usage,'$.output_tokens') BETWEEN 0 AND 9007199254740991 AND json_extract(safe_usage,'$.input_tokens')+json_extract(safe_usage,'$.output_tokens') <= 9007199254740991 THEN json_extract(safe_usage,'$.input_tokens')+json_extract(safe_usage,'$.output_tokens') WHEN nano_units=0 AND usage_json IS NULL AND (status=429 OR status BETWEEN 500 AND 599) THEN 0 END AS token_units FROM normalized;
